insert into public.discussions (id, source, content, tags, published_at, is_synthetic) values
  ('00000000-0000-4000-8000-000000000001', 'Demo Forum', 'What does term life insurance actually cover? I keep seeing the phrase but the explanations I find are all marketing. Looking for a plain-language overview of how term coverage works.', array['term life','coverage','education'], '2026-10-02T09:14:00Z', true),
  ('00000000-0000-4000-8000-000000000002', 'Demo Forum', 'How do policy exclusions work? I''d like to understand why some things aren''t covered even though the policy seems broad. Any general explainers on exclusions and how to read them?', array['exclusions','policy','education'], '2026-10-04T16:40:00Z', true),
  ('00000000-0000-4000-8000-000000000003', 'Demo Q&A', 'General question: what is the difference between term and whole life insurance? Not looking for a recommendation, just trying to learn the vocabulary.', array['term life','whole life','education'], '2026-10-06T11:05:00Z', true),
  ('00000000-0000-4000-8000-000000000004', 'Demo Community', 'Our small design studio is thinking about business continuity planning. What does key person insurance mean in general terms and how do companies usually think about it?', array['business continuity','key person','small business'], '2026-10-08T08:30:00Z', true),
  ('00000000-0000-4000-8000-000000000005', 'Demo Q&A', 'Before reviewing an existing policy, what questions should I ask myself? Looking for a general checklist of topics like deductibles, limits and renewal terms.', array['policy review','deductible','checklist'], '2026-10-09T13:22:00Z', true),
  ('00000000-0000-4000-8000-000000000006', 'Demo Forum', 'Can someone explain what an insurance deductible is and how it differs from a premium? I want to understand the basic terms before reading any documents.', array['deductible','premium','education'], '2026-10-11T10:00:00Z', true),
  ('00000000-0000-4000-8000-000000000007', 'Demo Community', 'What is the difference between an insurance broker and an agent? Looking for a general explanation of how each one works.', array['broker','agent','education'], '2026-10-13T15:45:00Z', true),
  ('00000000-0000-4000-8000-000000000008', 'Demo Q&A', 'How does renters insurance coverage work in general? Curious what categories it usually includes, like personal property and liability.', array['renters','coverage','education'], '2026-10-14T09:10:00Z', true),
  ('00000000-0000-4000-8000-000000000009', 'Demo Forum', 'Are there good beginner resources that explain how insurance underwriting works at a high level? I''m interested in the process, not any specific company.', array['underwriting','education','resources'], '2026-10-16T12:35:00Z', true),
  ('00000000-0000-4000-8000-000000000010', 'Demo Community', 'For a freelancer, what general types of business insurance exist? I''ve heard of professional liability and general liability but want a neutral overview.', array['freelance','liability','small business'], '2026-10-18T17:20:00Z', true),
  ('00000000-0000-4000-8000-000000000011', 'Demo Q&A', 'What does ''coverage limit'' mean on a policy, and how is it different from the amount an insurer actually pays out? Looking for a plain explanation.', array['coverage limit','policy','education'], '2026-10-20T08:55:00Z', true),
  ('00000000-0000-4000-8000-000000000012', 'Demo Forum', 'How do waiting periods work in insurance policies generally? I''d like to understand the concept before comparing documents.', array['waiting period','policy','education'], '2026-10-22T14:05:00Z', true),
  ('00000000-0000-4000-8000-000000000013', 'Demo Community', 'Our nonprofit board is discussing risk management. What are the usual categories of coverage organizations review, such as directors and officers or property?', array['nonprofit','risk management','coverage'], '2026-10-24T10:40:00Z', true),
  ('00000000-0000-4000-8000-000000000014', 'Demo Q&A', 'What does it mean when a policy is ''renewable'' or ''convertible''? Trying to understand the terminology used in term life documents.', array['term life','renewable','convertible'], '2026-10-26T11:30:00Z', true),
